class Editor:
    def __init__(self):
        self.current = ""
        self.undo_stack = []
        self.redo_stack = []

    def _change(self, new_text):
        self.undo_stack.append(self.current)
        self.redo_stack = []
        self.current = new_text

    def insert(self, text):
        self._change(self.current + text)

    def delete(self, n):
        self._change(self.current[:max(0, len(self.current) - n)])

    def undo(self):
        if self.undo_stack:
            self.redo_stack.append(self.current)
            self.current = self.undo_stack.pop()

    def redo(self):
        if self.redo_stack:
            self.undo_stack.append(self.current)
            self.current = self.redo_stack.pop()

    def text(self):
        return self.current

